python-fizzbuzz:
def fizzbuzz(n):
    out = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            out.append('FizzBuzz')
        elif i % 3 == 0:
            out.append('Fizz')
        elif i % 5 == 0:
            out.append('Buzz')
        else:
            out.append(str(i))
    return out

python-word-count:
def word_count(text):
    counts = {}
    for w in text.lower().split():
        counts[w] = counts.get(w, 0) + 1
    return counts

python-parse-int:
def parse_int(value):
    try:
        return int(value)
    except (ValueError, TypeError):
        return None

web-slugify:
import re

def slugify(title):
    return re.sub(r'[^a-z0-9]+', '-', title.lower()).strip('-')

web-status-category:
def status_category(code):
    names = {1: 'informational', 2: 'success', 3: 'redirect', 4: 'client error', 5: 'server error'}
    return names.get(code // 100, 'unknown') if 100 <= code < 600 else 'unknown'

web-parse-query-string:
def parse_query_string(query):
    out = {}
    for part in query.split('&'):
        if not part:
            continue
        key, _, value = part.partition('=')
        out[key] = value
    return out

ml-cosine-similarity:
import math

def cosine_similarity(a, b):
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(x * x for x in b))
    if na == 0 or nb == 0:
        return 0.0
    return sum(x * y for x, y in zip(a, b)) / (na * nb)
